"""Compile actual CAN error policy with synthetic inputs and mocked USB operations."""
from pathlib import Path
import subprocess
import tempfile
source = (Path(__file__).resolve().parents[1] / 'kernel/cancasexl.c').read_text()
halt = source[source.index('static int halt_channel('):source.index('/* Called by worker with io held')]
handler = source[source.index('static int decode_status('):source.index('/* Firmware event bytes 4..9')]
prefix = '\n#include <stdbool.h>\n#include <stdint.h>\n#include <string.h>\n#include <errno.h>\n#include <assert.h>\n#include <linux/can.h>\n#include <linux/can/error.h>\ntypedef uint8_t u8;\n#include <linux/can/netlink.h>\n#define spin_lock_irqsave(lock,flags) ((void)(lock), (flags)=0)\n#define spin_unlock_irqrestore(lock,flags) ((void)(lock), (void)(flags))\n#define net_device net\n#define netdev_priv(n) ((n)->priv)\n#define dev_warn(dev,fmt,ch,reason) ((void)(reason))\n#define dev_err(...) ((void)0)\n#define dev_warn_ratelimited(...) ((void)0)\nstruct net { void *priv; struct { unsigned rx_errors,tx_errors,rx_packets,rx_bytes,rx_dropped; } stats; };\nstruct xl { int unused; };\nstruct xl_chan { bool active, pending, pending_can_error; unsigned index; struct xl *xl; struct net *net; struct { struct { unsigned bus_error,error_warning,error_passive; } can_stats; enum can_state state; } can; int berr_lock; struct can_berr_counter bec; bool bec_valid; };\nstruct sk_buff { int unused; };\nstatic void can_change_state(struct net *n,struct can_frame *cf,enum can_state tx,enum can_state rx){\n struct xl_chan *c=n->priv;enum can_state state=tx>rx?tx:rx;\n assert(state!=c->can.state);\n if(state>c->can.state){if(state==CAN_STATE_ERROR_WARNING)c->can.can_stats.error_warning++;if(state==CAN_STATE_ERROR_PASSIVE)c->can.can_stats.error_passive++;}\n c->can.state=state;if(!cf)return;cf->can_id|=CAN_ERR_CRTL;\n if(state==CAN_STATE_ERROR_ACTIVE)cf->data[1]|=CAN_ERR_CRTL_ACTIVE;\n else {if(tx>=rx)cf->data[1]|=state==CAN_STATE_ERROR_WARNING?CAN_ERR_CRTL_TX_WARNING:CAN_ERR_CRTL_TX_PASSIVE;\n if(rx>=tx)cf->data[1]|=state==CAN_STATE_ERROR_WARNING?CAN_ERR_CRTL_RX_WARNING:CAN_ERR_CRTL_RX_PASSIVE;}\n}\nstatic bool isolate_can_errors, allocation_fail, diagnostic;\nstatic bool diagnostic_channel(struct xl_chan *c){(void)c;return diagnostic;}\nstatic void diagnostic_arm(struct xl_chan *c){(void)c;}\nstatic int stops,cancels,disabled,carrier,delivered,stop_result;\nstatic struct can_frame emitted;\nstatic struct sk_buff packet;\nstatic struct sk_buff *alloc_can_err_skb(struct net *n,struct can_frame **cf){(void)n;memset(&emitted,0,sizeof(emitted));emitted.can_id=CAN_ERR_FLAG;*cf=&emitted;return allocation_fail?0:&packet;}\nstatic void netif_rx(struct sk_buff *s){(void)s;delivered++;}\nstatic void netif_tx_disable(struct net *n){(void)n;disabled++;}\nstatic void netif_carrier_off(struct net *n){(void)n;carrier++;}\nstatic int stop_hw(struct xl_chan *c){(void)c;stops++;return stop_result;}\nstatic void cancel_tx(struct xl_chan *c){(void)c;cancels++;}\n'
checks = '\nint main(void) {\n struct net n={0}, peer={0}; struct xl_chan c={.active=true,.pending=true,.net=&n};\n u8 r[24]={2}; n.priv=&c; r[10]=8; r[11]=16; r[14]=0xd9;\n assert(can_error(&c,r)==0 && c.active && c.pending_can_error);\n assert(stops==0 && cancels==0 && (emitted.can_id & CAN_ERR_ACK));\n assert(n.stats.tx_errors==1 && peer.stats.tx_errors==0);\n c.pending_can_error=false; r[14]=0x79;\n assert(can_error(&c,r)==0 && c.active && !c.pending_can_error);\n r[10]=2; r[12]=150; assert(can_error(&c,r)==0 && c.can.state==CAN_STATE_ERROR_PASSIVE);\n u8 status[24]={4}; status[11]=8;\n assert(controller_status(&c,status)==0 && c.can.state==CAN_STATE_ERROR_ACTIVE);\n struct can_berr_counter bec; assert(xl_get_berr_counter(&n,&bec)==0);\n allocation_fail=true; r[10]=8; r[14]=0xd9;\n assert(can_error(&c,r)==0 && c.active && c.pending_can_error);\n allocation_fail=false; isolate_can_errors=true;\n assert(can_error(&c,r)==0 && !c.active && stops==1 && cancels==1);\n assert(c.can.state==CAN_STATE_STOPPED && !c.pending_can_error);\n c.active=true; isolate_can_errors=false; status[11]=0xff;\n assert(controller_status(&c,status)==0 && !c.active && stops==2);\n c.active=true; stop_result=-EPROTO; r[10]=0xff;\n assert(can_error(&c,r)==-EPROTO && c.active && cancels==2);\n return 0;\n}\n'
with tempfile.TemporaryDirectory() as tmp:
    path = Path(tmp)
    (path / 'test.c').write_text(prefix + halt + handler + checks)
    subprocess.run(['cc', '-std=c11', '-Wall', '-Wextra', '-Werror', str(path / 'test.c'), '-o', str(path / 'test')], check=True)
    subprocess.run([str(path / 'test')], check=True)
print('PASS: continuing/restrictive CAN errors, pending TX, unknown status and stop-command failure')
